test_cases.assertion_pseudocode:
malformed = '{{malformed: [unclosed, key: }'
try:
    result = extract_session_summary(malformed)
except Exception:
    fail('extract_session_summary raised on malformed input')
assert result == (None, [], [], [])

for malformed in ['{bad json:', None.__class__.__name__, '\x00\xff', '<broken>']:
    result = extract_session_summary(malformed)
    assert result == (None, [], [], []), f'Failed for input: {malformed}'

property_tests.invariant_check:
mock_provider.ingest.side_effect = exc_type(exc_message)
try:
    session_result = pipeline.run_full_session()
except Exception as e:
    fail(f'Exception propagated to runner: {e}')
# session must be considered successful

for triage_input in [None, make_triage(affected_files=[]), make_triage(affected_files=None)]:
    try:
        pipeline._retrieve_knowledge(triage=triage_input)
    except AttributeError:
        fail('AttributeError raised for triage_input=' + str(triage_input))
    kw = mock_provider.retrieve.call_args.kwargs
    assert kw.get('file_footprint') is None
